arguments.command:
cd /workspace/submission/src && python3 - <<'PYEOF'
p='de/rub/nds/tlsattacker/core/quic/serializer/frame/StreamFrameSerializer.java'
s=open(p).read()
s=s.replace("""    @Override
    protected byte[] serializeBytes() {
        writeFrameType();
        writeStreamId();
        if (frame.getOffset() != null) {
            writeOffset();
        }
        if (frame.getLength() != null) {
            writeLength();
        }
        writeData();
        return getAlreadySerialized();
    }""","""    @Override
    protected byte[] serializeBytes() {
        writeFrameType();
        QuicFrameType frameType = QuicFrameType.getFrameType(frame.getFrameType().getValue());
        writeStreamId();
        if (hasOffsetField(frameType)) {
            writeOffset();
        }
        if (hasLengthField(frameType)) {
            writeLength();
        }
        writeData();
        return getAlreadySerialized();
    }

    /** The offset field is only present for the OFF variants. */
    private static boolean hasOffsetField(QuicFrameType frameType) {
        switch (frameType) {
            case STREAM_FRAME_OFF:
            case STREAM_FRAME_OFF_FIN:
            case STREAM_FRAME_OFF_LEN:
            case STREAM_FRAME_OFF_LEN_FIN:
                return true;
            default:
                return false;
        }
    }

    /** The length field is only present for the LEN variants. */
    private static boolean hasLengthField(QuicFrameType frameType) {
        switch (frameType) {
            case STREAM_FRAME_LEN:
            case STREAM_FRAME_LEN_FIN:
            case STREAM_FRAME_OFF_LEN:
            case STREAM_FRAME_OFF_LEN_FIN:
                return true;
            default:
                return false;
        }
    }""")
open(p,'w').write(s)
PYEOF
cd /workspace && python3 build.py /workspace/submission/src /workspace/tmp/classes 2>&1|head -5 && for f in t1 t2 t3 t4 t5 t6 t7; do python3 dev/$f.py 2>&1|tail -1; done && python3 check.py /workspace/submission/src|tail -1
